SPECIAL = {"the": "", "The": "", "of": "", "and": "и", "SSR": "ССР", "SFR": "СФР", "SSSR": "СССР", "SR": "СР", "ABC": "АБК",
           "KMT": "Гоминьдан", "Kuomintang": "Гоминьдан"}


def _gender(adj, g):
    """Согласует прилагательное на -ий/-ый/-ой с родом g (m/f/n/p)."""
    if g == "m" or not adj:
        return adj
    stem = adj
    for suf in ("ский", "ний", "ый", "ий", "ой"):
        if adj.endswith(suf):
            stem = adj[: -len(suf)]
            tail = {"ский": "ск", "ний": "ни", "ый": "", "ий": "", "ой": ""}[suf]
            hard = suf in ("ый", "ой")
            ends = {"f": "ая" if hard or suf == "ский" else "яя", "n": "ое" if hard or suf == "ский" else "ее", "p": "ые" if hard or suf == "ский" else "ие"}
            if suf == "ий":
                ends = {"f": "ая", "n": "ое", "p": "ие"}
            return stem + tail + ends[g]
    return adj


def translate(text):
    """Возвращает русский текст или None, если в строке есть неизвестные слова."""
    if "$" in text and "OVERLORDADJ" not in text and not re.search(r"\$\w+\$", text):
        return None
    toks = re.findall(r"\$\w+\$|[A-Za-z'\-]+|[^A-Za-z'\-\$]+", text)
    items = []  # (kind, ru, gender)
    unknown = False
    for t in toks:
        if re.fullmatch(r"\$\w+\$", t):
            items.append(("var", t, None)); continue
        if not re.search(r"[A-Za-z]", t):
            items.append(("sep", t, None)); continue
        if t in SPECIAL:
            if SPECIAL[t]:
                items.append(("word", SPECIAL[t], None))
            continue
        if t in NOUNS:
            ru, g = NOUNS[t]
            items.append(("noun", ru, g)); continue
        if t in ADJ:
            items.append(("adj", ADJ[t], None)); continue
        if t in GEO:
            items.append(("geo", t, None)); continue
        unknown = True
    if unknown:
        return None
    gender = "m"
    for k, ru, g in items:
        if k == "noun":
            gender = g
            break
    # слова-прилагательные, стоящие до первого существительного, согласуем; «страна» после него остаётся названием
    out, seen_noun = [], False
    for i, (k, ru, g) in enumerate(items):
        if k == "noun":
            seen_noun = True
            out.append(ru)
        elif k == "adj":
            out.append(_gender(ru, gender) if not seen_noun else ru)
        elif k == "geo":
            name, adj = GEO[ru]
            has_noun_after = any(x[0] == "noun" for x in items[i + 1:])
            if has_noun_after and not seen_noun:
                out.append(_gender(adj, gender))
            else:
                out.append(name)
        else:
            out.append(ru)
    s = "".join(out)
    s = re.sub(r"[ \t]+", " ", s).strip()
    return s or None
